}

/// @brief  Enumeration for the account sync status.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 3.0 @endif
abstract class account_sync_state_e {
  /// < Account sync is invalid
  static const int ACCOUNT_SYNC_INVALID = 0;

  /// < Account sync not supported
  static const int ACCOUNT_SYNC_NOT_SUPPORT = 1;

  /// < Account sync supported but all synchronization functionalities are off
  static const int ACCOUNT_SYNC_STATUS_OFF = 2;

  /// < Account sync support and sync status is idle
  static const int ACCOUNT_SYNC_STATUS_IDLE = 3;

  /// < Account sync support and sync status is running
  static const int ACCOUNT_SYNC_STATUS_RUNNING = 4;

  /// <  NOT USED, WILL BE REMOVED TO PREVENT BUILD ERROR
  static const int ACCOUNT_SUPPORTS_SYNC = 5;

  /// <  NOT USED, WILL BE REMOVED TO PREVENT BUILD ERROR
  static const int ACCOUNT_NOT_SUPPORTS_SYNC = 6;
